<script>
$(async function() {
    toastr.options = { "positionClass": "toast-bottom-right", "timeOut": "4000" };

    // ==========================================
    // 0. 穿透引擎与API获取 (不变)
    // ==========================================
    const ST_WIN = window.parent || window || top;
    function getSTFn(fnName) {
        if (typeof ST_WIN[fnName] === 'function') return ST_WIN[fnName];
        if (typeof globalThis !== 'undefined' && typeof globalThis[fnName] === 'function') return globalThis[fnName];
        return null;
    }

    const api_getCharWorldbookNames = getSTFn('getCharWorldbookNames');
    const api_getWorldbook = getSTFn('getWorldbook');
    const api_updateWorldbookWith = getSTFn('updateWorldbookWith');
    const api_getLastMessageId = getSTFn('getLastMessageId');

    function tryApplyStoryLogic(stat_data) {
        let fn = getSTFn('calculateStoryLogic');
        if (typeof fn === 'function') {
            try { return fn(stat_data); } catch (e) { console.warn("Story Logic Sync Failed:", e); }
        }
        return stat_data;
    }

    // ==========================================
    // 1. 状态管理 (不变)
    // ==========================================
    let cachedStoryMap = null;
    let targetBookName = null;
    let initEntryUid = null;    // [initvar]
    let openingEntryUid = null; // [opening]
    let cachedOpeningContent = "";

    // UI 内部状态
    let state = {
        isRover: true,
        myGender: '男', 
        npcGender: '女'
    };

    // ==========================================
    // 2. UI 渲染逻辑 (动效优化：添加ID，防止事件覆盖重绘)
    // ==========================================
    function renderGenderSelector() {
        const $container = $('#gender-selection-area');
        let html = '';

        if (state.isRover) {
            html = `
            <div class="gender-grid rover-mode">
                <div class="gender-card ${state.myGender === '男' ? 'selected' : ''}" onclick="window.selectMyGender('男')" id="my-card-male">
                    <div class="img-wrap"><img src="https://s41.ax1x.com/2026/02/25/pZxkYvT.png"></div>
                    <div class="card-label">男漂泊者</div>
                </div>
                <div class="gender-card ${state.myGender === '女' ? 'selected' : ''}" onclick="window.selectMyGender('女')" id="my-card-female">
                    <div class="img-wrap"><img src="https://s41.ax1x.com/2026/02/25/pZxkJ2V.png"></div>
                    <div class="card-label">女漂泊者</div>
                </div>
            </div>`;
        } else {
            html = `
            <div class="gender-grid normal-mode">
                <div class="gender-card normal-btn ${state.myGender === '男' ? 'selected' : ''}" onclick="window.selectMyGender('男')" id="my-btn-male">
                    ♂️ 男
                </div>
                <div class="gender-card normal-btn ${state.myGender === '女' ? 'selected' : ''}" onclick="window.selectMyGender('女')" id="my-btn-female">
                    ♀️ 女
                </div>
                <div class="gender-card normal-btn ${state.myGender === '未知' ? 'selected' : ''}" onclick="window.selectMyGender('未知')" id="my-btn-unknown">
                    ⚧️ 未知
                </div>
            </div>`;
        }
        $container.html(html);
    }

    function updateNpcGenderUI() {
        $('#npc-card-male').toggleClass('selected', state.npcGender === '男');
        $('#npc-card-female').toggleClass('selected', state.npcGender === '女');
    }

    window.selectMyGender = (gender) => {
        state.myGender = gender;
        // 核心修改点：不再使用 renderGenderSelector() 暴力重绘销毁DOM导致过渡动画丢失，
        // 而是采用与 NPC 性别选择一样的方法，精细化 Toggle Class 保留过渡动画！
        if (state.isRover) {
            $('#my-card-male').toggleClass('selected', gender === '男');
            $('#my-card-female').toggleClass('selected', gender === '女');
        } else {
            $('#my-btn-male').toggleClass('selected', gender === '男');
            $('#my-btn-female').toggleClass('selected', gender === '女');
            $('#my-btn-unknown').toggleClass('selected', gender === '未知');
        }
    };

    window.selectNpcGender = (gender) => {
        state.npcGender = gender;
        updateNpcGenderUI();
    };

    // ==========================================
    // 3. 事件绑定
    // ==========================================

    // 淡入淡出切换 Rover 模式
    $('#ww-play-rover').on('change', function() {
        const isChecked = $(this).is(':checked');
        const $area = $('#gender-selection-area');

        $area.addClass('fading-out');

        setTimeout(() => {
            state.isRover = isChecked;
            if (state.isRover && state.myGender === '未知') state.myGender = '男';
            renderGenderSelector();
            $area.removeClass('fading-out');

            if (!state.isRover) {
                $('#ooc-warning').slideDown();
                // 新增：显示 AI 完善按钮
                $('#ai-refine-container').slideDown();
            } else {
                $('#ooc-warning').slideUp();
                // 新增：隐藏 AI 完善按钮
                $('#ai-refine-container').slideUp();
            }
        }, 250);
    });

    $('#ww-npc-exists').on('change', function() {
        const isChecked = $(this).is(':checked');
        if (isChecked) $('#npc-anim-box').addClass('open');
        else $('#npc-anim-box').removeClass('open');
    });

    $('#ww-is-story-mode').on('change', function() {
        const isChecked = $(this).is(':checked');
        if (isChecked) $('#story-anim-box').addClass('open');
