      $floatWin.draggable({
          cancel: '#wb-float-auto-toggle, #wb-float-close, .wb-float-toggle-expand',
          containment: 'window',
          start: function() { isDragging = true; },
          stop: function(event, ui) {
              SWITCHER_STATE.floatPos = { top: ui.position.top + 'px', left: ui.position.left + 'px' };
