    // 世界书模式时：静默无痕的同步引擎
    async function syncFeixunToWorldbook() {
        try {
            let chatVars = getVariables({ type: 'chat' });
            let chatUid = chatVars.fx_wb_uid;
            if (!chatUid) {
                chatUid = generateUUID();
